package com.example.jwtlogin.security.jwt;
import com.example.jwtlogin.security.services.UserDetailsServiceImpl; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class AuthTokenFilter extends OncePerRequestFilter { @Autowired private JwtUtils jwtUtils; @Autowired private UserDetailsServiceImpl userDetailsService; @Override protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain) throws ServletException, IOException { try{ String jwt=parseJwt(req); if(jwt!=null && jwtUtils.validateJwtToken(jwt)){ String u=jwtUtils.getUserNameFromJwtToken(jwt); UserDetails d=userDetailsService.loadUserByUsername(u); UsernamePasswordAuthenticationToken auth=new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()); auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req)); SecurityContextHolder.getContext().setAuthentication(auth); } } catch(Exception e){} chain.doFilter(req,res); } private String parseJwt(HttpServletRequest r){ String h=r.getHeader("Authorization"); if(h!=null && h.startsWith("Bearer ")) return h.substring(7); return null; } }
